    entries: list[tuple[str, Any, str, Dict[str, Any]]],
) -> list[tuple[str, Any, str, Dict[str, Any]]]:
    if os.getenv("HIKAFLOW_ENABLE_LEGACY_ALIASES", "0").strip().lower() not in {"1", "true", "yes", "on"}:
